    return true;
  }
  if (process.platform === "linux" && old.identity) {
    const space = seen.find((one) => one.pid === old.pid)?.pidNs;
    return seen.some(
      (one) =>
        space !== undefined &&
        one.pidNs === space &&
        one.pid !== old.pid &&
        !(one.ppid === old.pid && one.command === ANCHOR_SLEEP)
