			css: 'external',
		});

		const style = document.createElement('style');
		style.textContent = css.code;
		document.head.appendChild(style);

		const componentModule = new Blob([js.code], { type: 'application/javascript' });
		const componentUrl = URL.createObjectURL(componentModule);
		const Component = await import(componentUrl).then(module => module.default);
		URL.revokeObjectURL(componentUrl);

		mount(Component, {
			target: document.body,
			props: {
				name: 'World',
			},
		});
	</script>
</body>
</html>
```

(If you want to have the component code in the HTML, there are some ways to do it, but you have to fight the HTML parser because Svelte code is not valid HTML.)

